// Cloudflare Worker "meow-feedback" on meow.pocketjoystudio.com: the page the win-back email buttons open.
// /f?t=<token>&r=<reason> shows the chosen reason (changeable), asks "would you come back?" and an optional note.
// The browser posts each answer straight to the workstation's edge function winback-feedback (integrations/winback.sql),
// which checks the token; this Worker stores nothing itself. It also serves the email images at /img/<name>.png
// (IMAGES at the bottom, generated from emails/img). Paste this file into the Worker editor in the Cloudflare dashboard.
// The page is 喵的，又要上班了's; when another product gets a letter, give its links &p=<product> and pick the name,
// cat and store link here by p.
const API = "https://bpovoxjdqdwhhlfwgpep.supabase.co/functions/v1/winback-feedback";
const IMG = "https://sonia6891.github.io/meow-work-app";
const APP = "https://apps.apple.com/tw/app/id6817588985";

const page = (t, r) => `<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>謝謝您的回覆｜喵的，又要上班了</title>
<link rel="icon" href="${IMG}/app-icon-v178-180.png">
<style>
:root{--bg:#f3e6cf;--card:#fffaf0;--soft:#f6ead3;--ink:#4a3426;--muted:#8a6d55;--line:#d9bf9a;--red:#b63a32}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,"PingFang TC","Noto Sans TC","Microsoft JhengHei",sans-serif;line-height:1.7}
.wrap{max-width:520px;margin:0 auto;padding:24px 16px 40px}
.brand{display:flex;align-items:center;justify-content:center;gap:10px;font-weight:800;font-size:17px;margin-bottom:16px}
.brand img{width:36px;height:36px;border-radius:9px}
.card{background:var(--card);border:2px dashed #c9a57a;border-radius:22px;padding:22px 20px}
.cat{display:block;margin:0 auto 6px;width:130px;height:130px}
h1{font-size:21px;text-align:center;margin:4px 0 14px}
h2{font-size:16px;margin:20px 0 10px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.grid3{grid-template-columns:1fr 1fr 1fr}
button.chip{font:inherit;font-size:15px;font-weight:700;color:var(--ink);background:var(--card);border:1.5px solid var(--line);border-radius:12px;padding:11px 6px;cursor:pointer}
button.chip.on{background:var(--red);border-color:var(--red);color:#fff}
textarea{width:100%;min-height:110px;font:inherit;font-size:15px;color:var(--ink);background:var(--soft);border:1.5px solid var(--line);border-radius:12px;padding:12px}
.send{display:block;width:100%;margin-top:14px;font:inherit;font-size:17px;font-weight:800;color:#fff;background:var(--red);border:0;border-radius:999px;padding:13px}
.note{font-size:13px;color:var(--muted);text-align:center;margin-top:10px}
.saved{font-size:13px;color:#3d7a52;min-height:20px;text-align:center}
.done{text-align:center}
.hide{display:none}
a{color:var(--red)}
</style></head><body><div class="wrap">
<div class="brand"><img src="${IMG}/app-icon-v178-180.png" alt="">喵的，又要上班了</div>
<div class="card" id="form">
  <img class="cat" src="/img/hero.png" alt="" style="width:120px;height:auto">
  <h1>謝謝您願意告訴我 🐾</h1>
  <h2>關掉續訂的主要原因是？</h2>
  <div class="grid" data-k="reason">
    <button class="chip" data-v="price">💰 價格</button>
    <button class="chip" data-v="feature">🧩 少了功能</button>
    <button class="chip" data-v="bug">🐛 遇到問題</button>
    <button class="chip" data-v="notneeded">😴 暫時用不到</button>
    <button class="chip" data-v="other" style="grid-column:1/-1">💬 其他原因</button>
  </div>
  <h2>如果之後改善了，您會考慮回來嗎？</h2>
  <div class="grid grid3" data-k="comeback">
    <button class="chip" data-v="yes">會</button>
    <button class="chip" data-v="maybe">也許</button>
    <button class="chip" data-v="no">不會</button>
  </div>
  <h2>還有什麼想對我說的嗎？（可以不填）</h2>
  <textarea id="c" placeholder="例如：希望多一個什麼功能、哪裡用起來不順手……"></textarea>
  <div class="saved" id="s"></div>
  <button class="send" id="go">送出</button>
  <div class="note">每一則我都會親自看。—— Sonia</div>
</div>
<div class="card done hide" id="done">
  <img class="cat" src="${IMG}/assets/v4/cat-offwork-v1.webp" alt="">
  <h1>收到了，真的謝謝您！</h1>
  <p>您的意見會直接變成下一版的改進方向。<br>祝您每天上班順順利利，薪水越來越多！🐾</p>
  <p class="note">想再看看 App？<a href="${APP}">打開 App Store</a></p>
</div>
</div>
<script>
const T=${JSON.stringify(t)}, R=${JSON.stringify(r)};
const s=document.getElementById("s");
async function save(body){
  if(!T){s.textContent="這個連結好像不完整，可以直接回信告訴我 🙏";return false}
  try{const res=await fetch(${JSON.stringify(API)},{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(Object.assign({t:T},body))});
    const j=await res.json();if(!j.ok)throw 0;s.textContent="已記下 ✓";return true}
  catch(e){s.textContent="沒存到，請再按一次，或直接回信告訴我";return false}
}
document.querySelectorAll("[data-k]").forEach(g=>g.addEventListener("click",e=>{
  const b=e.target.closest("button.chip");if(!b)return;
  g.querySelectorAll(".chip").forEach(x=>x.classList.toggle("on",x===b));
  save({[g.dataset.k]:b.dataset.v});
}));
if(R){const b=document.querySelector('[data-k="reason"] [data-v="'+R+'"]');if(b){b.classList.add("on");save({reason:R})}}
document.getElementById("go").addEventListener("click",async()=>{
  const c=document.getElementById("c").value.trim();
  if(c&&!(await save({comment:c})))return;
  document.getElementById("form").classList.add("hide");document.getElementById("done").classList.remove("hide");scrollTo(0,0);
});
</script></body></html>`;

export default {
  async fetch(req) {
    const u = new URL(req.url);
    if (u.pathname.startsWith("/img/")) {
      const b = IMAGES[u.pathname.slice(5)];
      if (!b) return new Response("not found", { status: 404 });
      return new Response(Uint8Array.from(atob(b), (c) => c.charCodeAt(0)), { headers: { "content-type": "image/png", "cache-control": "public, max-age=31536000" } });
    }
    if (u.pathname === "/f") {
      const t = /^[0-9a-f]{24}$/.test(u.searchParams.get("t") || "") ? u.searchParams.get("t") : "";
      const r = ["price", "feature", "bug", "notneeded", "other"].includes(u.searchParams.get("r")) ? u.searchParams.get("r") : "";
      return new Response(page(t, r), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    return Response.redirect(APP, 302);
  },
};

// Email images (base64 PNG), generated from emails/img/icon.png, hero-q.png, payday-hd-q.png.
const IMAGES = {
  "icon.png": "",
  "hero.png": "",
  "payday.png": "",
};
